func:
// ============================================
// PROSES PESAN MQTT
// Smart Smoke Detection & Air Ventilation
// Metode: ADC DELTA terhadap baseline
// 10 OUTPUT
// ============================================

const T = String(msg.topic || '');

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function toBool(v) {
  return v === true || v === 1 ||
    String(v).toLowerCase() === 'true' ||
    String(v) === '1' ||
    String(v).toLowerCase() === 'on';
}

const p2 = n => String(n).padStart(2, '0');
const now = new Date();

const hhmm =
  p2(now.getHours()) + ':' +
  p2(now.getMinutes()) + ':' +
  p2(now.getSeconds());

// ============================================
// STATUS DASHBOARD DAN LOG
// ============================================

let last = flow.get('last') || {
  status: null,
  ket: '',
  fan: 0,
  fan1: 0,
  fan2: 0,
  fan3: 0,
  fan4: 0,
  buzzer: 0,
  servo1: 0,
  servo2: 0,
  mode: 'AUTO',
  flame: 0,
  online: null
};

let log = flow.get('log') || [];
let logChanged = false;

const out = [
  null, null, null, null, null,
  null, null, null, null, null
];

function addLog(status, ket) {
  log.unshift({
    time: hhmm,
    status: status,
    ket: ket
  });

  if (log.length > 8) {
    log.length = 8;
  }

  logChanged = true;
}

const statusText = {
  AMAN: 'Kondisi normal',
  WASPADA: 'Indikasi perubahan kualitas udara',
  BAHAYA: 'Bahaya terdeteksi'
};

// ============================================
// A. DATA SENSOR
// ============================================

if (T.endsWith('/sensor')) {

  const d = msg.payload;

  if (!d || typeof d !== 'object') return null;

  const smoke = num(d.smoke);
  const air = num(d.air);
  const co = num(d.co);

  const bs = num(d.bs);
  const ba = num(d.ba);
  const bc = num(d.bc);

  // Data ADC dan baseline harus lengkap
  if (
    [smoke, air, co, bs, ba, bc]
      .some(v => v === null)
  ) {
    return null;
  }

  // ========================================
  // HITUNG ADC DELTA
  // ========================================

  const smokeDelta = smoke - bs;
  const airDelta = air - ba;
  const coDelta = co - bc;

  const temp = num(d.temp);
  const hum = num(d.hum);

  // ========================================
  // OUTPUT 1: GAUGE MQ-2
  // ========================================

  out[0] = {
    payload: smokeDelta
  };

  // ========================================
  // OUTPUT 2: GAUGE MQ-135
  // ========================================

  out[1] = {
    payload: airDelta
  };

  // ========================================
  // OUTPUT 3: GAUGE MQ-7
  // ========================================

  out[2] = {
    payload: coDelta
  };

  // ========================================
  // OUTPUT 4: GAUGE SUHU
  // ========================================

  if (temp !== null) {
    out[3] = {
      payload: temp
    };
  }

  // ========================================
  // OUTPUT 5: GAUGE KELEMBAPAN
  // ========================================

  if (hum !== null) {
    out[4] = {
      payload: hum
    };
  }

  // ========================================
  // OUTPUT 6: GRAFIK GAS
  // ========================================

  out[5] = [
    {
      topic: 'MQ-2 Delta ADC',
      payload: smokeDelta
    },
    {
      topic: 'MQ-135 Delta ADC',
      payload: airDelta
    },
    {
      topic: 'MQ-7 Delta ADC',
      payload: coDelta
    }
  ];

  // ========================================
  // OUTPUT 7: GRAFIK SUHU DAN KELEMBAPAN
  // ========================================

  const th = [];

  if (temp !== null) {
    th.push({
      topic: 'Suhu (°C)',
      payload: temp
    });
  }

  if (hum !== null) {
    th.push({
      topic: 'Kelembapan (%)',
      payload: hum
    });
  }

  if (th.length > 0) {
    out[6] = th;
  }

  // ========================================
  // UPDATE STATUS API UNTUK DASHBOARD
  // ========================================

  last.flame = toBool(d.flame) ? 1 : 0;

  // Simpan nilai sensor terakhir
  last.smokeDelta = smokeDelta;
  last.airDelta = airDelta;
  last.coDelta = coDelta;

  // ========================================
  // OUTPUT 10: DATA KE DATABASE
  // ========================================

  out[9] = {
    topic: msg.topic,

    payload: {
      ...d,

      // Nilai ADC delta
      smoke_delta: smokeDelta,
      air_delta: airDelta,
      co_delta: coDelta,

      // PPM dan indeks belum digunakan
      smoke_ppm: null,
      air_index: null,
      co_ppm: null,
      co_index: null,

      // Metode pengolahan
      detection_method: 'ADC_DELTA',
      threshold_version: 'ADC_DELTA_V1',

      // Nama kolom yang digunakan database
      suhu: temp,
      kelembapan: hum
    }
  };
}

// ============================================
// B. DATA STATUS AKTUATOR
// ============================================

else if (T.endsWith('/status')) {

  const s = msg.payload;

  if (!s || typeof s !== 'object') return null;

  if (s.status && s.status !== last.status) {
    addLog(
      s.status,
      statusText[s.status] || ''
    );
  }

  last.status = s.status || last.status;

  last.ket = statusText[last.status] || '';

  last.fan1 = toBool(s.fan1) ? 1 : 0;
  last.fan2 = toBool(s.fan2) ? 1 : 0;
  last.fan3 = toBool(s.fan3) ? 1 : 0;
  last.fan4 = toBool(s.fan4) ? 1 : 0;

  last.fan = (
    last.fan1 ||
    last.fan2 ||
    last.fan3 ||
    last.fan4
  ) ? 1 : 0;

  last.buzzer = toBool(s.buzzer) ? 1 : 0;

  // Posisi servo dibaca dari status aktual ESP32
  last.servo1 = toBool(s.servo1) ? 1 : 0;
  last.servo2 = toBool(s.servo2) ? 1 : 0;

  last.mode = s.mode || last.mode;
}

// ============================================
// C. STATUS ONLINE ESP32
// ============================================

else if (T.endsWith('/online')) {

  const on =
    String(msg.payload).toLowerCase() === 'online';

  if (last.online !== null && last.online !== on) {

    addLog(
      on ? 'AMAN' : 'OFFLINE',
      on
        ? 'Perangkat online kembali'
        : 'Perangkat offline'
    );
  }

  last.online = on;
}

// Topic tidak dikenal
else {
  return null;
}

// ============================================
// OUTPUT 8: PANEL STATUS
// ============================================

flow.set('last', last);
flow.set('log', log);

out[7] = {
  payload: Object.assign({}, last, {
    servo: (last.servo1 || last.servo2)
      ? 'BUKA'
      : 'TUTUP',
    time: hhmm
  })
};

// ============================================
// OUTPUT 9: EVENT LOG
// ============================================

if (logChanged) {
  out[8] = {
    payload: log
  };
}

return out;

// ============================================
// FUNCTION 2 - SIMPAN DATA SENSOR KE MYSQL
// Smart Smoke Detection
// Metode ADC DELTA
// Penyimpanan setiap 10 detik
// ============================================

const d = msg.payload;

if (!d || typeof d !== 'object') {
    return null;
}

// ============================================
// 1. FUNGSI KONVERSI ANGKA
// ============================================

function num(v) {
    if (v === null || v === undefined || v === '') {
        return null;
    }

    const n = Number(v);

    return Number.isFinite(n) ? n : null;
}

// ============================================
// 2. VALIDASI DATA ADC DAN BASELINE
// ============================================

const smoke = num(d.smoke);
const air = num(d.air);
const co = num(d.co);

const bs = num(d.bs);
const ba = num(d.ba);
const bc = num(d.bc);

// Semua ADC dan baseline wajib tersedia
if (
    [smoke, air, co, bs, ba, bc]
        .some(v => v === null)
) {
    node.warn('Data ADC atau baseline tidak lengkap. Data tidak disimpan.');
    return null;
}

// ============================================
// 3. HITUNG ADC DELTA
// ============================================

// Hitung ulang agar data database konsisten
const smokeDelta = smoke - bs;
const airDelta = air - ba;
const coDelta = co - bc;

// ============================================
// 4. NORMALISASI FLAME
// ============================================

const flame =
    d.flame === true ||
        d.flame === 1 ||
        String(d.flame).toLowerCase() === 'true' ||
        String(d.flame) === '1' ||
        String(d.flame).toLowerCase() === 'on'
        ? 1 : 0;

// ============================================
// 5. DATA SUHU DAN KELEMBAPAN
// ============================================

const suhu = num(d.suhu !== undefined ? d.suhu : d.temp);

const kelembapan = num(
    d.kelembapan !== undefined ? d.kelembapan : d.hum
);

// ============================================
// 6. BATASI PENYIMPANAN 10 DETIK
// ============================================

const now = Date.now();
const lastInsert = flow.get('lastInsert') || 0;

if (now - lastInsert < 10000) {
    return null;
}

// ============================================
// 7. QUERY INSERT MYSQL
// ============================================

msg.topic = `
INSERT INTO sensor_log (
    smoke,
    air,
    co,

    bs,
    ba,
    bc,

    smoke_delta,
    air_delta,
    co_delta,

    flame,
    suhu,
    kelembapan,

    detection_method,
    threshold_version
)
VALUES (
    :smoke,
    :air,
    :co,

    :bs,
    :ba,
    :bc,

    :smoke_delta,
    :air_delta,
    :co_delta,

    :flame,
    :suhu,
    :kelembapan,

    :detection_method,
    :threshold_version
)
`;

// ============================================
// 8. DATA PARAMETER KE MYSQL
// ============================================

msg.payload = {

    // ADC mentah
    smoke: smoke,
    air: air,
    co: co,

    // Baseline
    bs: bs,
    ba: ba,
    bc: bc,

    // Hasil perhitungan ADC delta
    smoke_delta: smokeDelta,
    air_delta: airDelta,
    co_delta: coDelta,

    // Sensor tambahan
    flame: flame,
    suhu: suhu,
    kelembapan: kelembapan,

    // Metode pengolahan
    detection_method: 'ADC_DELTA',
    threshold_version: 'ADC_DELTA_V1'
};

// Simpan waktu insert terakhir
flow.set('lastInsert', now);

return msg;

const s = msg.payload;
if (!s || typeof s !== 'object' || !s.status) return null;

const kini = [s.status, s.fan ? 1 : 0, s.buzzer ? 1 : 0, s.servo ? 1 : 0, s.mode || 'AUTO'].join('|');
const lalu = flow.get('prevEvent');
if (lalu === kini) return null;
flow.set('prevEvent', kini);

const statusBerubah = !lalu || lalu.split('|')[0] !== s.status;
const KET = { AMAN: 'Kondisi normal', WASPADA: 'Kualitas udara menurun', BAHAYA: 'Bahaya terdeteksi' };

msg.topic = 'INSERT INTO event_log (jenis, keterangan, kipas, buzzer, servo, mode) VALUES (:jenis, :ket, :kipas, :buzzer, :servo, :mode)';
msg.payload = {
    jenis: s.status,
    ket: statusBerubah ? (KET[s.status] || '') : 'Perubahan kipas/mode manual',
    kipas: s.fan ? 1 : 0, buzzer: s.buzzer ? 1 : 0, servo: s.servo ? 1 : 0, mode: s.mode || 'AUTO'
};
return msg;

const sql = String(msg.topic || "");
if (!/^\s*SELECT\b/i.test(sql) || !/FROM\s+event_log\b/i.test(sql)) return null;
if (!Array.isArray(msg.payload)) return null;

const fmt = (v) => {
    if (v === null || v === undefined) return "-";
    if (typeof v === "string") return v.replace("T", " ").replace(/\.\d+Z?$/, "");
    return new Date(v).toLocaleString("id-ID", { timeZone: "Asia/Jakarta", hour12: false });
};
const onoff = (v) => Number(v) === 1 ? "ON" : "OFF";
const openclose = (v) => Number(v) === 1 ? "BUKA" : "TUTUP";

msg.payload = msg.payload.map(r => ({
    "Waktu": fmt(r.waktu),
    "Jenis": r.jenis,
    "Keterangan": r.keterangan,
    "Kipas": onoff(r.kipas),
    "Buzzer": onoff(r.buzzer),
    "Servo": openclose(r.servo),
    "Mode": r.mode
}));
return msg;

const sql = String(msg.topic || "");

// Hanya menerima SELECT sensor_log
if (
    !/^\s*SELECT\b/i.test(sql) ||
    !/FROM\s+sensor_log\b/i.test(sql)
) {
    return null;
}

// Pastikan hasil MySQL berupa array
if (!Array.isArray(msg.payload)) {
    node.warn("Hasil sensor_log bukan array.");
    return null;
}

const fmt = (v) => {
    if (v === null || v === undefined) return "-";

    if (typeof v === "string") {
        return v.replace("T", " ").replace(/\.\d+Z?$/, "");
    }

    const d = new Date(v);

    if (isNaN(d.getTime())) return "-";

    return d.toLocaleString("id-ID", {
        timeZone: "Asia/Jakarta",
        hour12: false
    });
};

const num = (v) => {
    if (v === null || v === undefined || v === "") return "-";

    const n = Number(v);
    return Number.isFinite(n) ? n.toFixed(1) : "-";
};

const api = (v) => {
    return (
        v === true ||
        Number(v) === 1 ||
        String(v).toLowerCase() === "true" ||
        String(v).toLowerCase() === "on"
    ) ? "Ya" : "Tidak";
};

msg.payload = msg.payload.map(r => ({
    "Waktu": fmt(r.waktu),

    "MQ-2 ADC": num(r.smoke),
    "MQ-2 Baseline": num(r.bs),
    "MQ-2 Delta": num(r.smoke_delta),

    "MQ-135 ADC": num(r.air),
    "MQ-135 Baseline": num(r.ba),
    "MQ-135 Delta": num(r.air_delta),

    "MQ-7 ADC": num(r.co),
    "MQ-7 Baseline": num(r.bc),
    "MQ-7 Delta": num(r.co_delta),

    "Api": api(r.flame),
    "Suhu (°C)": num(r.suhu),
    "Kelembapan (%)": num(r.kelembapan)
}));

node.warn("Jumlah data sensor ditampilkan: " + msg.payload.length);

return msg;

if (typeof msg.payload !== "string") return null;

const P = {
    "15m": { interval: "15 MINUTE", batas: 100 },
    "1h": { interval: "1 HOUR", batas: 400 },
    "3h": { interval: "3 HOUR", batas: 1100 },
    "6h": { interval: "6 HOUR", batas: 2200 },
    "12h": { interval: "12 HOUR", batas: 3300 }
};

const kunci = P[msg.payload]
    ? msg.payload
    : (flow.get("periode") || "1h");

flow.set("periode", kunci);

const { interval, batas } = P[kunci];

// Query riwayat sensor
const sensor = {
    topic:
        "SELECT waktu, smoke, air, co, bs, ba, bc, " +
        "smoke_delta, air_delta, co_delta, " +
        "flame, suhu, kelembapan " +
        "FROM sensor_log " +
        "WHERE waktu >= NOW() - INTERVAL " +
        interval + " " +
        "ORDER BY waktu DESC LIMIT " + batas,
    payload: {}
};

// Query riwayat kejadian
const kejadian = {
    topic:
        "SELECT waktu, jenis, keterangan, kipas, buzzer, `mode`, servo " +
        "FROM event_log " +
        "WHERE waktu >= NOW() - INTERVAL " +
        interval + " " +
        "ORDER BY waktu DESC LIMIT 500",
    payload: {}
};

// Satu output Function 4, dua pesan menuju MySQL
return [[sensor, kejadian]];

const p = msg.payload || {};
if (p.type !== "message") return null;

const chatId = String(p.chatId || "");
const isiPesan = String(p.content || "").trim();
const cmd = isiPesan.toLowerCase().split(/[\s@]/)[0];

// =====================================
// PERINTAH ADMIN: SETUJUI / TOLAK
// =====================================
const adminMatch = isiPesan.match(
    /^\/(setujui|tolak)(?:@\w+)?\s+(\d+)$/i
);

if (adminMatch) {
    msg.telegramSenderId = chatId;
    msg.adminCommandText = isiPesan;

    return [null, null, msg];
}

// =====================================
// FUNGSI BANTU
// =====================================
const balas = (t) => ({
    payload: {
        chatId: chatId,
        type: "message",
        content: t
    }
});

const kode = (k) => ({ payload: k });

const statusAktuator = (nilai, aktif, mati) =>
    nilai ? aktif : mati;

// =====================================
// DAFTAR PERINTAH
// =====================================
const PERINTAH = {
    // FAN 1
    "/fan1_on": ["FAN1_ON", "FAN 1 dinyalakan"],
    "/fan1_off": ["FAN1_OFF", "FAN 1 dimatikan"],

    // FAN 2
    "/fan2_on": ["FAN2_ON", "FAN 2 dinyalakan"],
    "/fan2_off": ["FAN2_OFF", "FAN 2 dimatikan"],

    // FAN 3
    "/fan3_on": ["FAN3_ON", "FAN 3 dinyalakan"],
    "/fan3_off": ["FAN3_OFF", "FAN 3 dimatikan"],

    // FAN 4
    "/fan4_on": ["FAN4_ON", "FAN 4 dinyalakan"],
    "/fan4_off": ["FAN4_OFF", "FAN 4 dimatikan"],

    // SERVO 1
    "/servo1_buka": ["SERVO1_OPEN", "SERVO 1 dibuka"],
    "/servo1_tutup": ["SERVO1_CLOSE", "SERVO 1 ditutup"],

    // SERVO 2
    "/servo2_buka": ["SERVO2_OPEN", "SERVO 2 dibuka"],
    "/servo2_tutup": ["SERVO2_CLOSE", "SERVO 2 ditutup"],

    // MODE
    "/auto": ["MODE_AUTO", "Kembali ke mode otomatis"],

    // TEST
    "/tes": ["TEST", "Uji aktuator dijalankan (hanya saat status AMAN)"]
};

// =====================================
// HELP / START
// =====================================
if (cmd === "/start" || cmd === "/help") {
    return [null, balas([
        "🤖 PERINTAH SMART SMOKE DETECTION",
        "",
        "📊 INFORMASI:",
        "/status - kondisi terakhir",
        "/riwayat - 5 kejadian terakhir",
        "",
        "🌀 KONTROL KIPAS:",
        "/fan1_on - nyalakan FAN 1",
        "/fan1_off - matikan FAN 1",
        "/fan2_on - nyalakan FAN 2",
        "/fan2_off - matikan FAN 2",
        "/fan3_on - nyalakan FAN 3",
        "/fan3_off - matikan FAN 3",
        "/fan4_on - nyalakan FAN 4",
        "/fan4_off - matikan FAN 4",
        "",
        "🪟 KONTROL SERVO:",
        "/servo1_buka - buka SERVO 1",
        "/servo1_tutup - tutup SERVO 1",
        "/servo2_buka - buka SERVO 2",
        "/servo2_tutup - tutup SERVO 2",
        "",
        "⚙️ MODE SISTEM:",
        "/auto - kembali ke mode otomatis",
        "/tes - uji aktuator (saat AMAN)",
        "/kalibrasi - kalibrasi baseline",
        "/kalibrasi_ya - konfirmasi kalibrasi",
        "",
        "👤 ADMIN:",
        "/setujui CHAT_ID - setujui akun",
        "/tolak CHAT_ID - tolak akun"
    ].join("\n")), null];
}

// =====================================
// STATUS SISTEM
// =====================================
if (cmd === "/status") {
    const s = flow.get("statusTerakhir");
    const d = flow.get("sensorTerakhir") || {};
    const on = flow.get("tgOnline");

    if (!s) {
        return [null, balas(
            "Belum ada data status dari ESP32."
        ), null];
    }

    return [null, balas([
        "📊 STATUS SMART SMOKE DETECTION",
        "",
        "Kondisi: " + (s.status || "-") +
            (on === false ? " ⚠️ (ESP32 OFFLINE, data lama)" : ""),
        "Mode: " + (s.mode || "-"),
        "",
        "🌀 STATUS KIPAS:",
        "FAN 1: " + statusAktuator(s.fan1, "ON", "OFF"),
        "FAN 2: " + statusAktuator(s.fan2, "ON", "OFF"),
        "FAN 3: " + statusAktuator(s.fan3, "ON", "OFF"),
        "FAN 4: " + statusAktuator(s.fan4, "ON", "OFF"),
        "",
        "🔊 Buzzer: " + statusAktuator(s.buzzer, "ON", "OFF"),
        "",
        "🪟 STATUS SERVO:",
        "SERVO 1: " + statusAktuator(s.servo1, "BUKA", "TUTUP"),
        "SERVO 2: " + statusAktuator(s.servo2, "BUKA", "TUTUP"),
        "",
        "🌡️ DATA SENSOR:",
        "Suhu: " + (d.temp ?? "-") + " °C",
        "Kelembapan: " + (d.hum ?? "-") + " %",
        "Asap (ADC): " + (d.smoke ?? "-"),
        "Udara (ADC): " + (d.air ?? "-"),
        "CO (ADC): " + (d.co ?? "-"),
        "Api: " + (d.flame ? "TERDETEKSI" : "Tidak ada")
    ].join("\n")), null];
}

// =====================================
// RIWAYAT
// =====================================
if (cmd === "/riwayat") {
    const log = (flow.get("log") || []).slice(0, 5);

    if (!log.length) {
        return [null, balas(
            "Belum ada kejadian tercatat."
        ), null];
    }

    return [
        null,
        balas(
            "📋 KEJADIAN TERAKHIR:\n" +
            log.map(e =>
                e.time + "  " + e.status + "  " + e.ket
            ).join("\n")
        ),
        null
    ];
}

// =====================================
// EKSEKUSI PERINTAH AKTUATOR
// =====================================
if (PERINTAH[cmd]) {
    const [k, ket] = PERINTAH[cmd];

    return [
        kode(k),
        balas(
            "✅ " + ket +
            "\n\nCatatan keselamatan:" +
            "\n- Saat BAHAYA, seluruh kipas dipaksa ON." +
            "\n- Buzzer aktif saat BAHAYA." +
            "\n- Jika api terdeteksi, servo dipaksa TUTUP."
        ),
        null
    ];
}

// =====================================
// KALIBRASI
// =====================================
if (cmd === "/kalibrasi") {
    flow.set("tgKalibrasi", Date.now());

    return [null, balas(
        "⚠️ KALIBRASI SENSOR\n\n" +
        "Kalibrasi mengambil baseline dari kondisi udara saat ini.\n" +
        "Pastikan udara bersih sebelum melanjutkan.\n\n" +
        "Ketik /kalibrasi_ya dalam 60 detik untuk konfirmasi."
    ), null];
}

if (cmd === "/kalibrasi_ya") {
    const t = flow.get("tgKalibrasi") || 0;
    flow.set("tgKalibrasi", 0);

    if (!t || Date.now() - t > 60000) {
        return [null, balas(
            "⚠️ Permintaan kalibrasi kedaluwarsa.\n" +
            "Ketik /kalibrasi lagi."
        ), null];
    }

    return [
        kode("CALIBRATE"),
        balas("✅ Perintah kalibrasi dikirim."),
        null
    ];
}

// =====================================
// PERINTAH TIDAK DIKENAL
// =====================================
return [
    null,
    balas("❌ Perintah tidak dikenal.\nKetik /help untuk melihat daftar perintah."),
    null
];

// ============================================
// LOGIKA CLOUD
// Smart Smoke Detection & Air Ventilation
// 4 Kipas + 2 Servo
// Metode: ADC DELTA
// ============================================

// ============================================
// 1. AMBANG SENSOR
// HARUS SAMA DENGAN FIRMWARE ESP32
// ============================================

// MQ-2
const SMOKE_WARN_DELTA = 300;
const SMOKE_DANGER_DELTA = 500;

// MQ-135
const AIR_WARN_DELTA = 300;
const AIR_DANGER_DELTA = 500;

// MQ-7
const CO_WARN_DELTA = 300;
const CO_DANGER_DELTA = 500;

// DHT22
const TEMP_WARN_C = 40.0;
const TEMP_DANGER_C = 50.0;

// Histeresis
const HYST_DELTA = 50;
const HYST_TEMP_C = 2.0;

// Konfirmasi perubahan status
const CONFIRM_UP = 2;
const CONFIRM_DOWN = 5;

const RANK = {
    AMAN: 0,
    WASPADA: 1,
    BAHAYA: 2
};

// ============================================
// 2. FUNGSI BANTU
// ============================================

function num(v) {
    if (v === null || v === undefined || v === '') {
        return null;
    }

    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function toBool(v) {
    return v === true ||
        v === 1 ||
        String(v).toLowerCase() === 'true' ||
        String(v) === '1' ||
        String(v).toLowerCase() === 'on';
}

// ============================================
// 3. AMBIL DATA SENSOR
// ============================================

const d = msg.payload;

if (!d || typeof d !== 'object') {
    return null;
}

const smoke = num(d.smoke);
const air = num(d.air);
const co = num(d.co);

const bs = num(d.bs);
const ba = num(d.ba);
const bc = num(d.bc);

const temp = num(d.temp);

// Data ADC dan baseline wajib tersedia
if (
    [smoke, air, co, bs, ba, bc]
        .some(v => v === null)
) {
    return null;
}

// ============================================
// 4. HITUNG ADC DELTA
// ============================================

const dSmoke = smoke - bs;
const dAir = air - ba;
const dCo = co - bc;

const api = toBool(d.flame);

const manual = num(d.mm) === 1 || d.mm === true;

// ============================================
// 5. STATUS INTERNAL
// ============================================

let st = flow.get('lg') || {
    status: 'AMAN',
    up: 0,
    down: 0,
    pending: null,
    lastUp: null,
};

// Pastikan status tersimpan valid
if (!Object.prototype.hasOwnProperty.call(RANK, st.status)) {
    st = {
        status: 'AMAN',
        up: 0,
        down: 0,
        pending: null,
        lastUp: null
    };
}

// Deteksi ESP32 restart
const uptime = num(d.up);

if (uptime !== null) {

    if (st.lastUp !== null && uptime < st.lastUp) {
        st.up = 0;
        st.down = 0;
        st.pending = null;
    }

    st.lastUp = uptime;
}

// ============================================
// 6. HITUNG HISTERESIS
// ============================================

const wasDanger = st.status === 'BAHAYA';
const wasActive = st.status !== 'AMAN';

const hd = wasDanger ? HYST_DELTA : 0;
const hw = wasActive ? HYST_DELTA : 0;
const ht = wasDanger ? HYST_TEMP_C : 0;

// ============================================
// 7. EVALUASI MASING-MASING SENSOR
// ============================================

// MQ-2
const smokeWarn =
    dSmoke >= SMOKE_WARN_DELTA - hw;

const smokeDanger =
    dSmoke >= SMOKE_DANGER_DELTA - hd;

// MQ-135
const airWarn =
    dAir >= AIR_WARN_DELTA - hw;

const airDanger =
    dAir >= AIR_DANGER_DELTA - hd;

// MQ-7
const coWarn =
    dCo >= CO_WARN_DELTA - hw;

const coDanger =
    dCo >= CO_DANGER_DELTA - hd;

// DHT22
const tempWarn =
    temp !== null &&
    temp >= TEMP_WARN_C - (wasActive ? HYST_TEMP_C : 0);

const tempDanger =
    temp !== null &&
    temp >= TEMP_DANGER_C - ht;

// Flame
// Api langsung BAHAYA tanpa menunggu konfirmasi.
const flameDanger = api;

// ============================================
// 8. LOGIKA OR: SALAH SATU SENSOR CUKUP
// ============================================

const dangerSources = [];

if (smokeDanger) dangerSources.push('MQ-2');
if (airDanger) dangerSources.push('MQ-135');
if (coDanger) dangerSources.push('MQ-7');
if (tempDanger) dangerSources.push('DHT22');
if (flameDanger) dangerSources.push('FLAME');

const danger = dangerSources.length > 0;

// WASPADA
const warning =
    smokeWarn ||
    airWarn ||
    coWarn ||
    tempWarn;

// Tentukan target status
let calon;

if (danger) {
    calon = 'BAHAYA';
}
else if (warning) {
    calon = 'WASPADA';
}
else {
    calon = 'AMAN';
}

// ============================================
// 9. UPDATE STATUS + KONFIRMASI
// ============================================

// Api langsung BAHAYA
if (api) {

    st.status = 'BAHAYA';
    st.up = 0;
    st.down = 0;
    st.pending = null;

}
else {

    const sekarang = RANK[st.status];
    const target = RANK[calon];

    if (target === sekarang) {

        st.up = 0;
        st.down = 0;
        st.pending = null;

    }

    // Kenaikan status
    else if (target > sekarang) {

        st.down = 0;

        if (st.pending !== calon) {
            st.pending = calon;
            st.up = 1;
        }
        else {
            st.up++;
        }

        if (st.up >= CONFIRM_UP) {

            st.status = calon;
            st.up = 0;
            st.down = 0;
            st.pending = null;
        }
    }

    // Penurunan status
    else {

        st.up = 0;

        if (st.pending !== calon) {
            st.pending = calon;
            st.down = 1;
        }
        else {
            st.down++;
        }

        if (st.down >= CONFIRM_DOWN) {

            st.status = calon;
            st.up = 0;
            st.down = 0;
            st.pending = null;
        }
    }
}

flow.set('lg', st);

// ============================================
// 10. SUMBER BAHAYA
// ============================================

let alarmSource = dangerSources.length
    ? dangerSources.join(', ')
    : (st.status === 'BAHAYA' ? 'HISTERESIS' : '-');

// ============================================
// 11. LOGIKA 4 KIPAS
// ============================================

let fan1 = false;
let fan2 = false;
let fan3 = false;
let fan4 = false;

// BAHAYA: semua kipas menyala
if (st.status === 'BAHAYA') {

    fan1 = true;
    fan2 = true;
    fan3 = true;
    fan4 = true;

}

// MODE MANUAL
else if (manual) {

    fan1 = num(d.f1m) === 1 && num(d.f1c) === 1;
    fan2 = num(d.f2m) === 1 && num(d.f2c) === 1;
    fan3 = num(d.f3m) === 1 && num(d.f3c) === 1;
    fan4 = num(d.f4m) === 1 && num(d.f4c) === 1;

}

// MODE AUTO - WASPADA
else if (st.status === 'WASPADA') {

    fan1 = true;
    fan2 = true;

}

// MODE AUTO - AMAN
// Semua kipas tetap mati.

// ============================================
// 12. LOGIKA BUZZER
// ============================================

const buzzer = st.status === 'BAHAYA';

// ============================================
// 13. LOGIKA 2 SERVO
// ============================================

let servo1 = 0;
let servo2 = 0;

// PRIORITAS 1: API
// Kedua servo wajib tertutup.
if (api) {

    servo1 = 0;
    servo2 = 0;

}

// PRIORITAS 2: BAHAYA NON-API
// Kedua servo terbuka.
else if (st.status === 'BAHAYA' && !api) {

    servo1 = 1;
    servo2 = 1;

}

// PRIORITAS 3: MANUAL
else if (manual) {

    servo1 =
        num(d.s1m) === 1 && num(d.s1c) === 1 ? 1 : 0;

    servo2 =
        num(d.s2m) === 1 && num(d.s2c) === 1 ? 1 : 0;
}

// AUTO AMAN/WASPADA: kedua servo tertutup.

// ============================================
// 14. KIRIM PERINTAH KE ESP32
// ============================================

msg.payload = {

    status: st.status,

    fan1: fan1 ? 1 : 0,
    fan2: fan2 ? 1 : 0,
    fan3: fan3 ? 1 : 0,
    fan4: fan4 ? 1 : 0,

    buzzer: buzzer ? 1 : 0,

    servo1: servo1,
    servo2: servo2,

    alarm_source: alarmSource,

    smoke_delta: dSmoke,
    air_delta: dAir,
    co_delta: dCo,

    flame: api ? 1 : 0,
    temp: temp
};

return msg;

const chatId = String(
    msg.originalMessage?.chat?.id || ""
);

msg.telegramChatId = chatId;

const type = msg.payload?.type;
const content = msg.payload?.content;

