    FROM telegram_users
    WHERE chat_id = :chatId
`;

msg.payload = {
    chatId: chatId
};

return msg;

const rows = msg.payload || [];
const chatId = String(msg.telegramChatId);

// Validasi hasil SELECT
if (!Array.isArray(rows)) {
    node.error(
        "Hasil SELECT bukan array: " +
        JSON.stringify(rows),
        msg
    );
    return null;
}

// =====================================
