    };

    return [null, msg];
}


// =====================================
// 4. SIMPAN DATA PENDAFTARAN SEMENTARA
// =====================================

// BAGIAN BARU YANG DITAMBAHKAN
msg.registration = {
    chatId: chatId,
    phone: contact.phone_number,
