`;

msg.payload = {
    chatId: chatId,
    phone: contact.phone_number,
    firstName: contact.first_name || ""
};

return [msg, null];

const chatId = String(
    msg.telegramChatId ||
    msg.originalMessage?.chat?.id ||
    ""
);

msg.payload = {
    chatId: chatId,
    type: "message",
    content: "✅ Pendaftaran berhasil!\n\nNomor HP kamu sudah tersimpan dan sedang menunggu persetujuan admin.\n\nKamu akan mendapatkan akses setelah admin mengaktifkan akun."
};

return msg;

// =====================================
// NOTIFIKASI PENDAFTARAN ADMIN
// =====================================

const data = msg.registration;

if (!data || !data.chatId) {
    node.error("Data pendaftaran tidak ditemukan", msg);
    return null;
}

const userChatId = String(data.chatId);

// =====================================
