        [
            {
                text: "✅ SETUJUI",
                callback_data: "REG_APPROVE:" + userChatId
            },
            {
                text: "❌ TOLAK",
                callback_data: "REG_REJECT:" + userChatId
            }
        ]
    ]
};

// =====================================
