// =====================================

const senderId = String(
    msg.telegramSenderId ||
    msg.originalMessage?.from?.id ||
    msg.originalMessage?.chat?.id ||
    ""
);

// =====================================
// 2. AMBIL ISI PERINTAH
// =====================================

const command = String(
    msg.adminCommandText ||
    msg.originalMessage?.text ||
    msg.payload?.content ||
    ""
).trim();

node.warn("ISI COMMAND: " + command);
node.warn("SENDER ID: " + senderId);

// =====================================
