    /^\/(setujui|tolak)(?:@\w+)?(?:\s+(\d+))?$/i
);

// Bukan perintah admin
if (!match) {
    return [null, null, msg];
}

// =====================================
// 4. VALIDASI FORMAT
// =====================================

if (!match[2]) {
    msg.payload = {
        chatId: senderId,
        type: "message",
        content:
            "Format perintah salah.\n\n" +
            "Gunakan:\n" +
            "/setujui CHAT_ID\n" +
            "/tolak CHAT_ID"
    };

    return [null, msg, null];
}

// =====================================
// 5. VALIDASI ADMIN
// =====================================

const ADMIN_ID = "1834826609";

if (senderId !== ADMIN_ID) {
    msg.payload = {
        chatId: senderId,
        type: "message",
        content:
            "❌ Kamu tidak memiliki izin " +
            "menjalankan perintah admin."
    };

    return [null, msg, null];
}

// =====================================
// 6. SIMPAN DATA KEPUTUSAN
