const rows = msg.payload || [];

// Pastikan hasil query berupa array
if (!Array.isArray(rows)) {
    node.error(
        "Hasil query penerima bukan array: " +
        JSON.stringify(rows),
        msg
    );

    return null;
}

// Ambil semua akun yang aktif
const chatIds = rows
    .map(row => String(row.chat_id || "").trim())
    .filter(id => id !== "");

// Jika tidak ada penerima
if (chatIds.length === 0) {
    node.warn("Belum ada akun Telegram aktif");
    return null;
}

// Buat pesan untuk setiap penerima
const messages = chatIds.map(id => ({
    payload: {
        chatId: id,
        type: "message",
        content: msg.notifText
    }
}));

// Satu output, banyak pesan
return [messages];

const p = msg.payload || {};

// Ambil identitas pengirim tombol
const senderId = String(
    msg.originalMessage?.from?.id ||
    p.chatId ||
    ""
);

// ID admin yang diizinkan
const ADMIN_ID = "1834826609";

// Validasi admin
if (senderId !== ADMIN_ID) {
    node.warn("Tombol ditekan bukan oleh admin");
    return null;
}

// Ambil callback_data
const callback = String(p.content || "");

// Baca keputusan
const match = callback.match(
    /^(REG_APPROVE|REG_REJECT):(\d+)$/
);

if (!match) {
    node.warn("Callback tidak dikenal: " + callback);
    return null;
}

const aksi = match[1];
const userChatId = match[2];

// Terjemahkan tombol menjadi perintah admin
msg.telegramSenderId = senderId;

msg.adminCommandText =
    aksi === "REG_APPROVE"
        ? "/setujui " + userChatId
        : "/tolak " + userChatId;

// Teruskan ke Function deteksi perintah admin
return msg;
